static BOOL GenerateDump(EXCEPTION_POINTERS* pExceptionPointers)
{
	WCHAR* szAppName = L"JPEGView";
	DWORD dwBufferSize = MAX_PATH;
	HANDLE hDumpFile;
	SYSTEMTIME stLocalTime;
	MINIDUMP_EXCEPTION_INFORMATION ExpParam;

